// Step 1: Initialize a Symbol
const mySymbol = Symbol('description');
console.log(typeof mySymbol); // Expected: 'symbol'
console.log(mySymbol); // Output: Symbol(description)

// Step 2: Create an object using Symbol as a key
const myObject = {};
myObject[mySymbol] = 'Unique Value';
myObject['description'] = 'String Key Value';
console.log(myObject);

// Step 3: Comparing two Symbols
const symbol1 = Symbol('test');
const symbol2 = Symbol('test');
console.log(symbol1 === symbol2); // Expected: false

// Step 4: Using Symbol.for()
const globalSymbol = Symbol.for('global');
const sameGlobalSymbol = Symbol.for('global');
console.log(globalSymbol === sameGlobalSymbol); // Expected: true
console.log(Symbol.keyFor(globalSymbol)); // Expected: 'global'

// Primitive type example
let primitiveVar = 42;

// Reference type example
let referenceVar = { key: 'value' };

// Function to modify primitive type
function modifyPrimitive(primitive) {
  primitive = 100;
}

// Function to modify reference type
function modifyReference(reference) {
  reference.key = 'new value';
}

// Call functions and log results
modifyPrimitive(primitiveVar);
modifyReference(referenceVar);
console.log('Primitive Variable:', primitiveVar); // Expect: 42
console.log('Reference Variable:', referenceVar); // Expect: { key: 'new value' }

